//! Revisión de lectura: terna validada y HTML generado en Rust, sin JavaScript.
use std::{fs,io::{Read,Write},net::TcpListener,path::Path,time::Duration};
type R<T>=Result<T,Box<dyn std::error::Error>>;
#[derive(Debug)]struct Fila{c:Vec<String>}
fn filas(s:&str)->R<Vec<Fila>>{let mut out=vec![];for (i,l) in s.lines().skip(1).filter(|l|!l.is_empty()).enumerate(){let c:Vec<_>=l.split('\t').map(str::to_owned).collect();if c.len()!=7||c[0]!=format!("P{:02}",i+1)||!matches!(c[1].as_str(),"si"|"no")||!matches!(c[2].as_str(),"0"|"1"|"U"|"IT"){return Err("Fila inválida o desordenada".into())}out.push(Fila{c});}if out.len()!=25{return Err("Se requieren 25 posiciones".into())}Ok(out)}
fn contar(f:&[Fila],critica:bool)->[usize;4]{let mut n=[0;4];for x in f{if critica&&x.c[1]!="si"{continue}n[match x.c[2].as_str(){"0"=>0,"1"=>1,"U"=>2,_=>3}]+=1;}n}
fn esc(s:&str)->String{s.replace('&',"&amp;").replace('<',"&lt;").replace('>',"&gt;").replace('"',"&quot;").replace('\'',"&#39;")}
fn generar()->R<()>{let f=filas(&fs::read_to_string("evaluacion.tsv")?)?;let n=contar(&f,false);let c=contar(&f,true);if n!=[7,2,10,6]||c!=[6,2,8,4]{return Err("Recuento discordante con la revisión".into())}
let mut h=String::from("<!doctype html><html lang=\"es\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Revisión del examen Qwen80 Instruct</title><style>body{max-width:1000px;margin:3rem auto;padding:0 1rem;font:18px system-ui;color:#16334a;background:white}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eff4f8;padding:1rem}table{border-collapse:collapse;width:100%;margin:1.5rem 0}th,td{border:1px solid #cad5df;padding:.55rem;text-align:left}a{color:#0751a8}details{border:1px solid #cad5df;padding:1rem;margin:1rem 0}summary{cursor:pointer;font-weight:650}h1{font-size:2rem}small{line-height:1.6}.aviso{border-left:5px solid #aa5b00;padding:1rem;background:#fff6e9}</style><main><h1>Examen Qwen80 Instruct</h1><p>Ronda EVAL-PDQ-HCL-25-20260929/r1 · S39 / TT-0016 · 30 de septiembre de 2026.</p><p><strong>Ejecución terminada: 25 preguntas tramitadas, 19 respuestas finales y 6 impedimentos técnicos.</strong> Esta página conserva la corrección documental para revisión humana. La interfaz es de lectura y no ejecuta inferencias.</p><table><caption>Resultados de la corrección</caption><tr><th>Grupo</th><th>0 · Acierto</th><th>1 · Error penalizado</th><th>U · Indeterminación</th><th>Impedimento técnico</th></tr><tr><td>Total (25)</td><td>7</td><td>2</td><td>10</td><td>6</td></tr><tr><td>Críticas (20)</td><td>6</td><td>2</td><td>8</td><td>4</td></tr><tr><td>No críticas (5)</td><td>1</td><td>0</td><td>2</td><td>2</td></tr></table><p class=\"aviso\"><strong>Propuesta de dictamen: No apto en el alcance examinado</strong>, por dos errores en posiciones críticas (P07 y P19), pendiente de revisión humana. No se constituye un frame completo: los seis impedimentos carecen de valor ternario. Tampoco se infiere aptitud clínica ni del dominio completo.</p><p>Las diez U son respuestas finales de abstención o insuficientes para acreditar lo solicitado. Seis preguntas no produjeron respuesta final por rechazo instrumental; no se cuentan como U. Penalizaciones: dos valores 1, sin inventar una puntuación negativa adicional. La condición de aptitud exige todas las posiciones críticas en 0 y el umbral documentado floor(7n/9), que para n=25 es 19.</p><p><a href=\"/evaluacion.json\">Corrección trazable (JSON)</a> · <a href=\"/resultados.json\">Resultados originales cotejados (JSON)</a></p><h2>Las 25 posiciones</h2><p>Cada ficha muestra pregunta, respuesta original, referencia de corrección y justificación. P19 contiene una generalización absoluta que se somete expresamente a revisión humana. Las trazas MCP son copias derivadas de las solicitudes y respuestas conservadas; los originales permanecen en los paquetes de custodia.</p>");
for x in f{let c=x.c;h.push_str(&format!("<details id=\"{}\"><summary>{} · {} · {}</summary><h3>Pregunta</h3><p>{}</p><h3>Respuesta original</h3><pre>{}</pre><h3>Respuesta de referencia</h3><p>{}</p><h3>Fundamento de la valoración</h3><p>{}</p>",esc(&c[0]),esc(&c[0]),if c[1]=="si"{"Crítica"}else{"No crítica"},esc(&c[2]),esc(&c[3]),esc(&c[4]),esc(&c[6]),esc(&c[5])));if c[2]!="IT"{h.push_str(&format!("<p><a href=\"/trazas-mcp/{}.json\">Solicitudes y respuestas MCP conservadas</a></p>",c[0]));}h.push_str("</details>");}
h.push_str("<footer><p>Fuente delimitada: PDQ del NCI en español para profesionales sobre leucemia de células pilosas, copia congelada. La corrección no sustituye una valoración médica ni una recepción institucional.</p><p>Se conserva la presentación básica del cascarón anterior. Generación, validación y servicio local en Rust; JavaScript ausente.</p></footer></main></html>");fs::write("revision.html",h)?;fs::write("RECUENTO-RUST.json","{\"total\":25,\"respuestas_finales\":19,\"aciertos_0\":7,\"errores_1\":2,\"indeterminaciones_U\":10,\"impedimentos_tecnicos\":6,\"sin_ejecutar\":0,\"criticas\":{\"0\":6,\"1\":2,\"U\":8,\"impedimentos\":4},\"frame_completo\":false,\"propuesta\":\"No apto\",\"revision_humana\":\"pendiente\"}\n")?;println!("RECUENTO_CONFORME: 7/2/10; seis impedimentos excluidos; HTML de lectura generado");Ok(())}
fn servir()->R<()>{let listener=TcpListener::bind("127.0.0.1:18081")?;println!("REVISION_DISPONIBLE http://127.0.0.1:18081/");for stream in listener.incoming(){let mut stream=stream?;stream.set_read_timeout(Some(Duration::from_secs(3)))?;let mut b=[0u8;4096];let n=match stream.read(&mut b){Ok(n)=>n,Err(_)=>continue};let line=String::from_utf8_lossy(&b[..n]);let mut parts=line.lines().next().unwrap_or("").split_whitespace();let method=parts.next().unwrap_or("");let route=parts.next().unwrap_or("");let file=match route{"/"=>Some("revision.html"),"/evaluacion.json"=>Some("EVALUACION-TERNARIA.json"),"/resultados.json"=>Some("RESULTADOS-COTEJADOS.json"),_=>None};let trace=route.strip_prefix("/trazas-mcp/").filter(|s|s.len()==8&&s.starts_with('P')&&s.ends_with(".json")&&s[1..3].parse::<u8>().map(|v|(1..=25).contains(&v)).unwrap_or(false));let tracepath=trace.map(|s|format!("trazas-mcp/{s}"));let path=file.or(tracepath.as_deref());let (status,data,mime)=if method!="GET"{("405 Method Not Allowed",b"Solo lectura".to_vec(),"text/plain")}else if let Some(p)=path{match fs::read(Path::new(p)){Ok(d)=>("200 OK",d,if p.ends_with("html"){"text/html"}else{"application/json"}),Err(_)=>("404 Not Found",b"No disponible".to_vec(),"text/plain")}}else{("404 Not Found",b"No disponible".to_vec(),"text/plain")};let header=format!("HTTP/1.1 {status}\r\nContent-Type: {mime}; charset=utf-8\r\nContent-Length: {}\r\nContent-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'\r\nX-Content-Type-Options: nosniff\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n",data.len());let _=stream.write_all(header.as_bytes()).and_then(|_|stream.write_all(&data));}Ok(())}
fn main()->R<()>{match std::env::args().nth(1).as_deref(){Some("generar")=>generar(),Some("servir")=>servir(),_=>Err("Uso: generar | servir".into())}}
#[cfg(test)]mod tests{use super::*;#[test]fn escape(){assert_eq!(esc("<script>&\""),"&lt;script&gt;&amp;&quot;");}#[test]fn incompleto(){assert!(filas("id\n").is_err());}#[test]fn tecnico_fuera(){let f=vec![Fila{c:vec!["P01".into(),"si".into(),"IT".into()]},Fila{c:vec!["P02".into(),"si".into(),"U".into()]}];assert_eq!(contar(&f,false),[0,0,1,1]);}#[test]fn criticidad(){let f=vec![Fila{c:vec!["P01".into(),"no".into(),"1".into()]},Fila{c:vec!["P02".into(),"si".into(),"0".into()]}];assert_eq!(contar(&f,true),[1,0,0,0]);}}
